function parseInteger(text) {
  const match = /^(?:[+-]?(?:0|[1-9](?:_?[0-9])*)|0x[0-9a-fA-F](?:_?[0-9a-fA-F])*|0o[0-7](?:_?[0-7])*|0b[01](?:_?[01])*)$/.exec(text);
  if (!match || match[0] !== text) return null;
  const value = BigInt(text.replaceAll('_', ''));
  if (value < -(1n << 63n) || value > (1n << 63n) - 1n) return null;
  return value.toString();
}
module.exports = { parseInteger };
